<script setup lang="ts">
import {computed} from 'vue';import type {Account} from '../types';import {useData} from '../store';import {accountName,accountReportTime,date,duration,finite,remaining,sortRecentAccountDevices} from '../domain';
const props=defineProps<{item:Account}>();const data=useData(),left=computed(()=>remaining(props.item));const active=computed(()=>props.item.machines.filter(m=>m.stale==='green')),past=computed(()=>sortRecentAccountDevices(props.item.machines.filter(m=>m.stale!=='green')));
/** 功能：计算单窗口剩余，保留未知而非展示零；参数：已用比例；返回值：0至100或null。 */
function windowLeft(value:number|null){const used=finite(value);return used===null?null:Math.max(0,Math.min(100,100-used));}
</script>
<template><article class="account-card quota-account-card" :class="{danger:left!==null&&left<20,'account-idle':!item.in_use}"><header class="quota-card-heading"><div class="quota-card-identity"><h3 :title="accountName(item)">{{accountName(item)}}</h3><span class="small-label">{{item.owner||'负责人未设置'}}</span></div><el-tag size="small" :type="item.in_use?'success':'info'">{{item.in_use?`在用 · ${item.active_machine_count}台`:item.collected_at===null?'待采集':'离线历史'}}</el-tag></header><div class="quota-card-tags"><el-tag size="small" effect="plain">{{item.plan_type||'套餐未知'}}</el-tag><span class="small-label mono" :title="item.account_id||''">{{item.account_id?item.account_id.slice(0,8)+'…'+item.account_id.slice(-4):'身份未知'}}</span></div><el-alert v-if="item.divergence||item.reset_mismatch" title="设备读数存在差异，以最新账号快照为准" type="warning" :closable="false"/><div v-if="!item.windows.length" class="empty">尚无额度读数</div><div v-for="w in item.windows" :key="w.kind" class="quota-window"><div class="flex-between"><b>{{w.label}}</b><span class="quota-window-left" :class="{'orange':(windowLeft(w.used_percent)??100)<20}">{{windowLeft(w.used_percent)===null?'剩余未知':`剩余 ${windowLeft(w.used_percent)?.toFixed(0)}%`}}</span></div><el-progress v-if="finite(w.used_percent)!==null" :percentage="Math.max(0,Math.min(100,w.used_percent!))" :show-text="false" :status="(w.used_percent??0)>=80?'warning':undefined"/><div class="quota-meta"><span>{{finite(w.used_percent)===null?'已用未知':`已用 ${w.used_percent?.toFixed(1)}%`}}</span><span>{{w.reset_estimated?'推算重置':'重置'}}：{{w.resets_at===null?'未知':duration(w.resets_at-data.now)}}</span></div></div><div class="quota-card-devices"><template v-if="active.length"><span class="small-label">使用中的设备</span><div class="device-chips"><span v-for="m in active" :key="m.machine_id" class="device-chip">{{m.label}} · 在线</span></div></template><template v-if="past.length"><span class="small-label">最近使用过的设备</span><div class="device-chips"><span v-for="m in past.slice(0,3)" :key="m.machine_id" class="device-chip off" :title="m.last_reported_at==null?'该账号上报时间未知':`最后上报此账号额度：${date(m.last_reported_at)}`">{{m.label}} · 最后上报 {{accountReportTime(m.last_reported_at)}}</span><span v-if="past.length>3" class="small-label">另 {{past.length-3}} 台</span></div></template></div><footer class="quota-card-footer"><span>Credits：{{item.unlimited?'不限量':item.balance??'未知'}}</span><span :title="date(item.collected_at)">{{item.collected_at===null?'尚未采集':`采集于 ${date(item.collected_at)}`}}</span></footer><p v-if="!item.in_use&&item.collected_at!==null" class="small-label quota-history-note">历史读数，当前没有设备在线使用此账号。</p></article></template>
<style scoped>
.quota-account-card{padding:18px;min-height:320px;display:flex;flex-direction:column;gap:12px}.quota-card-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}.quota-card-identity{min-width:0}.quota-card-identity h3{margin:0 0 7px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:calc(15px * var(--app-font-scale, 1.2))}.quota-card-tags{display:flex;align-items:center;gap:10px}.quota-window{padding:12px 0;border-top:1px solid var(--line)}.quota-window-left{font-size:calc(20px * var(--app-font-scale, 1.2));font-variant-numeric:tabular-nums;font-weight:650}.quota-window :deep(.el-progress){margin-top:10px}.quota-meta{display:flex;flex-wrap:wrap;gap:6px;justify-content:space-between}.quota-card-devices{border-top:1px solid var(--line);padding-top:12px;display:grid;gap:7px}.quota-card-devices .device-chips{margin-top:0}.quota-card-footer{margin-top:auto;padding-top:10px;border-top:1px solid var(--line);display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px;font-size:calc(11px * var(--app-font-scale, 1.2));color:var(--muted)}.quota-history-note{margin:0}.account-idle{border-color:var(--line)}
</style>
